use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


/// Manager-worker pattern with two agents, Alice (manager) and Bob (worker).
async fn manager_worker_agent() -> anyhow::Result<()> {
    // Erase the model once and clone the handle for each agent.
    let model = OpenAI::from_env()?.completion(openai::GPT_5_5).erase();


    let bob = AgentBuilder::new(model.clone())
        .name("bob")
        .description("An employee who works in admin at FooBar Inc.")
        .preamble(
            "You are Bob, an employee in admin at FooBar Inc. Alice, your manager, \
             may ask you to do things. You need to do them.",
        )
        .build();


    let alice = AgentBuilder::new(model)
        .name("alice")
        .preamble("You are a manager in the admin department at FooBar Inc. You manage Bob.")
        .dynamic_tool(bob.into_tool()?)
        .default_max_turns(3)
        .build();


    let res = alice
        .prompt("Ask Bob to write an email for you and let me know what he has written.")
        .await?;


    println!("Response: {}", res.output());
    Ok(())
}

struct Translator(Agent);


#[derive(Deserialize)]
struct TranslatorArgs {
    text: String,
}


impl Tool for Translator {
    const NAME: &'static str = "translator";
    type Args = TranslatorArgs;
    type Output = String;
    type Error = PromptError;


    fn description(&self) -> String {
        "Translate any text to English.".to_string()
    }


    fn parameters(&self) -> serde_json::Value {
        json!({
            "type": "object",
            "properties": { "text": { "type": "string", "description": "Text to translate" } },
            "required": ["text"]
        })
    }


    async fn call(&self, _ctx: &mut ToolContext, args: Self::Args) -> Result<String, PromptError> {
        Ok(self.0.prompt(args.text).await?.output())
    }
}

use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


async fn research_and_write(topic: &str) -> anyhow::Result<String> {
    let model = OpenAI::from_env()?.completion(openai::GPT_5_5).erase();


    let historian = AgentBuilder::new(model.clone())
        .preamble("You summarize the history of a topic in five bullet points.")
        .build();
    let economist = AgentBuilder::new(model.clone())
        .preamble("You summarize the economics of a topic in five bullet points.")
        .build();
    let writer = AgentBuilder::new(model)
        .preamble("You turn research notes into a short, readable article.")
        .build();


    // Two independent workers, run concurrently.
    let (history, economics) = tokio::join!(historian.prompt(topic), economist.prompt(topic));


    // One dependent step that combines their output.
    let notes = format!(
        "History:\n{}\n\nEconomics:\n{}",
        history?.output(),
        economics?.output()
    );
    Ok(writer.prompt(notes).await?.output())
}

use rig::prelude::*;
use std::sync::Arc;
use tokio::sync::{mpsc, RwLock};


/// Messages exchanged between agents.
#[derive(Debug, Clone)]
enum AgentMessage {
    Task(String),
    Response(String, String), // (from_agent_id, content)
    Trigger(String),
    Shutdown,
}


/// An actor-based autonomous agent. Each holds its own Rig agent, an inbox,
/// its history, and channels to its peers.
struct AutonomousAgent {
    id: String,
    agent: Agent,
    history: Vec<String>,
    inbox: mpsc::Receiver<AgentMessage>,
    peers: Arc<RwLock<Vec<mpsc::Sender<AgentMessage>>>>,
}

use tokio::time::{interval, Duration};


impl AutonomousAgent {
    /// Broadcast a message to every registered peer.
    async fn broadcast(&self, message: AgentMessage) {
        for peer in self.peers.read().await.iter() {
            let _ = peer.send(message.clone()).await;
        }
    }


    async fn run(mut self) {
        let mut tick = interval(Duration::from_secs(10));
        loop {
            tokio::select! {
                Some(msg) = self.inbox.recv() => match msg {
                    AgentMessage::Shutdown => break,
                    AgentMessage::Task(task) => {
                        if let Ok(response) = self.agent.prompt(task).await {
                            let result = response.output();
                            self.history.push(result.clone());
                            self.broadcast(AgentMessage::Response(self.id.clone(), result)).await;
                        }
                    }
                    AgentMessage::Trigger(msg) => {
                        let _ = self.agent.prompt(msg).await;
                    }
                    AgentMessage::Response(from, content) => {
                        self.history.push(format!("From {from}: {content}"));
                    }
                },
                // Autonomous periodic self-check (external trigger)
                _ = tick.tick() => {
                    // e.g. summarize progress, enqueue follow-up work, etc.
                }
            }
        }
    }
}
